 function destination(s){const candidates=WorldMap.detail(s.kingdom).neighbors.map(n=>n.index).filter(k=>Ecology.canTravel(s,k));return candidates.length?candidates[(s.seed+s.job)%candidates.length]:null;}
 function matches(s,e){if(e.dynasty){if(!elite(s))return false;const t=status(s);if(t.withdrawn&&e.min>=18)return false;if(e.id==='dyn34-confirm'&&(t.order>1||s.humanOrigin.favor<50))return false;if(e.id==='dyn34-govern'){const p=FamilyWorld.primary(s);if(p?.alive&&Engine.biological(s)<40)return false;}}if(e.professionPattern)return s.job!==null&&new RegExp(e.professionPattern).test(JOBS[s.job]?.[0]||'');return true;}
 function next(s){if(s.race!==0)return null;const last=s.diary?.entries.find(e=>e.key?.startsWith('decision-dyn34-'));if(last&&s.age-last.age<2)return null;const e=records.find(e=>Engine.eligible(s,e));if(!e)return null;const out=JSON.parse(JSON.stringify(e));if(e.id==='dyn34-govern')out.text=(FamilyWorld.primary(s)?.alive?'ประมุขเดิมยื่นคำขอวางมือต่อสภา':'หลังการจากไปของประมุขเดิม สภาเปิดขั้นตอนส่งมอบ')+' คุณถูกเรียกมารับตรา พร้อมบัญชี ภาระ และเรื่องที่ยังแก้ไม่เสร็จ';if(out.professionPattern){const to=destination(s);if(to!==null){out.choices[1].label+=' · '+KINGDOMS[to][0];out.choices[1].effect.gold=-Economy.travelCost(s,to);out.choices[1].realmVisit=to;out.choices[1].hint=Economy.travelCost(s,to)+' ทอง · '+out.choices[1].hint}else out.choices.splice(1,1);}return out;}
